SELECT * FROM (SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'SLAB:'||slab_id||':received_at' event_id,'Slab Received' activity,received_at timestamp,slab_id source_key FROM slab_material WHERE received_at IS NOT NULL AND (1=1)) e JOIN slab_material s ON s.slab_id=e.source_key UNION ALL SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'SLAB:'||slab_id||':verified_at' event_id,'Slab Verified' activity,verified_at timestamp,slab_id source_key FROM slab_material WHERE verified_at IS NOT NULL AND (1=1)) e JOIN slab_material s ON s.slab_id=e.source_key UNION ALL SELECT e.event_id,'S:'||s.slab_id case_id,e.activity,e.timestamp FROM (SELECT 'SLAB:'||slab_id||':released_at' event_id,'Slab Released' activity,released_at timestamp,slab_id source_key FROM slab_material WHERE released_at IS NOT NULL AND (1=1)) e JOIN slab_material s ON s.slab_id=e.source_key) ORDER BY case_id,timestamp,event_id;
